import * as React from "react";
import { StyleSheet, View } from "react-native";
import Svg, { Circle, Path } from "react-native-svg";
import { LinearGradient } from "expo-linear-gradient";
import Animated, { Easing, interpolate, useAnimatedProps, useAnimatedStyle, useSharedValue, withDelay, withRepeat, withTiming, Extrapolation } from "react-native-reanimated";
import { lift, palette, useTheme } from "../theme";
import { Burst, useOnce } from "./motion";
// The ʿayn's geometry, shared with the web app (generated by scripts/brand-assets.mts).
import { AYN } from "../../../src/components/brand/wordmark-paths";

const AnimatedPath = Animated.createAnimatedComponent(Path);

/**
 * The mark (ʿAyn): the letter ع as one rounded stroke, the coral pupil in its
 * head, which calligraphers call the letter's eye.
 */
export function Mark({ size = 28, color, dot = palette.coral }: { size?: number; color?: string; dot?: string }) {
  const { c } = useTheme();
  const stroke = color ?? c.text;
  return (
    <Svg width={size} height={size} viewBox="0 0 64 64" accessibilityElementsHidden importantForAccessibility="no-hide-descendants">
      <Path d={AYN.d} fill="none" stroke={stroke} strokeWidth={AYN.stroke} strokeLinecap="round" strokeLinejoin="round" />
      <Circle cx={AYN.pupil.cx} cy={AYN.pupil.cy} r={AYN.pupil.r} fill={dot} />
    </Svg>
  );
}

/** The app symbol: the white ʿayn on a squircle tile, violet turning to navy, the pupil in coral. */
export function Symbol({ size = 40 }: { size?: number }) {
  const { c } = useTheme();
  const radius = size * 0.3;
  return (
    <View style={[{ width: size, height: size, borderRadius: radius, backgroundColor: palette.logoTo, alignItems: "center", justifyContent: "center" }, lift("glow", c, palette.logoFrom)]}>
      <View pointerEvents="none" style={[StyleSheet.absoluteFill, { borderRadius: radius, overflow: "hidden" }]}>
        <LinearGradient colors={[palette.logoFrom, palette.logoTo]} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={StyleSheet.absoluteFill} />
      </View>
      {/* In a View: on the web a bare <svg> would paint under the absolutely placed gradient. */}
      <View>
        <Mark size={size * 0.66} color={palette.white} />
      </View>
    </View>
  );
}

/**
 * The ʿayn, alive: the stroke draws itself, then the pupil lands. The loading
 * state while a scene is prepared (looping: it draws, rests, and draws again)
 * and the signature on the briefing and complete screens (once). Still under
 * reduced motion. Lavender-violet on the canvas; white on the highlight card.
 *
 * Played once with `burst`, the pupil pops as it lands: a ring and a few coral
 * particles, about a second (none under reduced motion). `onLand` fires at
 * that moment (at once when still).
 */
export function MarkLive({ width = 120, loop = true, color, onHero, burst, onLand }: { width?: number; loop?: boolean; color?: string; onHero?: boolean; burst?: boolean; onLand?: () => void }) {
  const { c, reduceMotion } = useTheme();
  const t = useSharedValue(reduceMotion ? 1 : 0);
  const stroke = color ?? (onHero ? "rgba(255,255,255,0.95)" : c.accentText);
  const dot = onHero ? palette.coral : c.signal;
  const size = width;

  React.useEffect(() => {
    if (reduceMotion) {
      t.value = 1;
      return;
    }
    t.value = 0;
    const run = withTiming(1, { duration: 1500, easing: Easing.out(Easing.cubic) });
    t.value = loop ? withRepeat(withDelay(500, run), -1, false) : withDelay(200, run);
  }, [loop, reduceMotion, t]);

  // The stroke draws over the first 70%; the pupil lands after it.
  const strokeProps = useAnimatedProps(() => ({ strokeDashoffset: interpolate(t.value, [0, 0.7], [AYN.length, 0], Extrapolation.CLAMP) }));
  const pupilStyle = useAnimatedStyle(() => {
    const k = interpolate(t.value, [0.66, 0.9], [0, 1], Extrapolation.CLAMP);
    const s = k < 0.7 ? interpolate(k, [0, 0.7], [0, 1.25]) : interpolate(k, [0.7, 1], [1.25, 1]);
    return { transform: [{ scale: s }], opacity: k > 0 ? 1 : 0 };
  });

  const pop = useSharedValue(0);
  const land = React.useCallback(() => {
    if (burst && !reduceMotion) pop.value = withTiming(1, { duration: 1000, easing: Easing.out(Easing.quad) });
    onLand?.();
  }, [burst, reduceMotion, onLand, pop]);
  useOnce(() => {
    "worklet";
    return !loop && t.value >= 0.83;
  }, land);

  const unit = size / 64;
  const pupil = AYN.pupil.r * 2 * unit;
  return (
    <View style={{ width: size, height: size }} accessibilityElementsHidden importantForAccessibility="no-hide-descendants">
      <Svg width={size} height={size} viewBox="0 0 64 64">
        <AnimatedPath d={AYN.d} fill="none" stroke={stroke} strokeWidth={AYN.stroke} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={`${AYN.length}`} animatedProps={strokeProps} />
      </Svg>
      <View style={{ position: "absolute", left: AYN.pupil.cx * unit - pupil / 2, top: AYN.pupil.cy * unit - pupil / 2, width: pupil, height: pupil }}>
        {burst && !reduceMotion ? <Burst t={pop} size={pupil} color={dot} /> : null}
        <Animated.View style={[{ width: pupil, height: pupil, borderRadius: pupil / 2, backgroundColor: dot }, pupilStyle]} />
      </View>
    </View>
  );
}
